def diagonal_beams(grid, period=4):
    """NxN grid where the top row's single pixel emits two diagonals of its color, and parallel diagonals one period to the left, below the anti-diagonal through the pixel, are drawn in the next color down."""
    c0, color = find_top_pixel(grid)
